package com.aveycole.agentlooper;
import android.app.*;
import android.content.*;
import android.graphics.*;
import android.os.*;
import android.view.*;
import java.io.*;

public final class AndroidSmokeTest extends Instrumentation {
    boolean captureTest;
    void capture(MainActivity a,Bundle result)throws Exception{
        runOnMainSync(()->{synchronized(a.engine){for(LoopEngine.Bank b:a.engine.banks)b.layers.clear();float[] own=new float[96000];for(int i=0;i<48000;i++)own[i*2]=own[i*2+1]=(float)(.2*Math.sin(2*Math.PI*330*i/48000));a.engine.banks[0].layers.add(new LoopEngine.Layer(own,"Own output",0));a.engine.banks[0].playing=true;}a.desiredMode=1;android.media.projection.MediaProjectionManager pm=(android.media.projection.MediaProjectionManager)a.getSystemService(android.content.Context.MEDIA_PROJECTION_SERVICE);a.startActivityForResult(pm.createScreenCaptureIntent(android.media.projection.MediaProjectionConfig.createConfigForDefaultDisplay()),11);});
        long end=System.currentTimeMillis()+45000;while((AudioService.mode!=1||!AudioService.current.ready)&&System.currentTimeMillis()<end)Thread.sleep(100);check(AudioService.mode==1&&AudioService.current.ready,"app-capture consent and startup");Thread.sleep(700);check(a.engine.inputPeak<.0001,"own playback excluded");
        runOnMainSync(()->a.startActivity(new Intent().setComponent(new ComponentName("com.aveycole.agentlooper.source","com.aveycole.agentlooper.source.SourceActivity"))));waitFor(()->a.engine.inputPeak>.1,"other app produces captured audio");runOnMainSync(()->{a.engine.banks[1].sync=true;a.engine.bpm=240;a.engine.countIn=0;a.engine.begin(1,false);});waitFor(()->!a.engine.banks[1].recording,"capture finishes in background");float[] recorded=a.engine.banks[1].layers.get(0).audio;check(recorded.length==96000,"one-second captured length: "+recorded.length+"; "+a.engine.message+"; bars="+a.engine.bars+" beats="+a.engine.beats);int crossings=0;for(int i=12001;i<36000;i++)if(recorded[(i-1)*2]<=0&&recorded[i*2]>0)crossings++;check(Math.abs(crossings*2-440)<20,"captured source frequency: "+crossings*2);result.putString("stream","PASS: Android playback-capture consent; native capture startup; own 330 Hz loop excluded; separate app 440 Hz captured; exact one-second take while other app foreground.");finish(Activity.RESULT_OK,result);
    }
    void check(boolean b,String s){if(!b)throw new AssertionError(s);}
    void waitFor(java.util.function.BooleanSupplier predicate,String message)throws Exception{long end=System.currentTimeMillis()+12000;while(!predicate.getAsBoolean()&&System.currentTimeMillis()<end)Thread.sleep(50);check(predicate.getAsBoolean(),message);}
    @Override public void onCreate(Bundle args){super.onCreate(args);captureTest=args!=null&&"true".equals(args.getString("capture"));start();}
    @Override public void onStart(){Bundle result=new Bundle();try{MainActivity a=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitFor(()->AudioService.current!=null&&AudioService.current.ready,"foreground audio ready: "+AudioService.engine.message);if(captureTest){capture(a,result);return;}long clock=a.engine.clock;waitFor(()->a.engine.clock>clock+4800,"audio callback advances");runOnMainSync(()->{synchronized(a.engine){a.engine.banks[0].layers.clear();a.engine.banks[1].layers.clear();for(LoopEngine.Bank b:a.engine.banks){b.playing=true;b.auto=false;b.sync=false;b.quantize=0;b.inputMode=0;b.waitInput=false;}float[] one=new float[96000],three=new float[288000];for(int i=0;i<48000;i++)one[i*2]=one[i*2+1]=(float)(.15*Math.sin(2*Math.PI*220*i/48000)*Math.exp(-(i%6000)/1700.0));for(int i=0;i<144000;i++)three[i*2]=three[i*2+1]=(float)(.12*Math.sin(2*Math.PI*330*i/48000)*Math.exp(-(i%16000)/5000.0));LoopEngine.Layer l=new LoopEngine.Layer(one,"Synth",a.engine.banks[0].frame);l.expanded=true;a.engine.banks[0].layers.add(l);a.engine.banks[0].origin=l.offset;a.engine.banks[1].layers.add(new LoopEngine.Layer(three,"Long loop",a.engine.banks[1].frame));a.engine.banks[1].origin=a.engine.banks[1].frame;}});waitFor(()->a.engine.outputPeak>.02,"loop output nonzero");waitForIdleSync();Thread.sleep(300);runOnMainSync(()->{LooperView.Hit knob=null;for(LooperView.Hit h:a.surface.hits)if(h.knob==2){knob=h;break;}check(knob!=null,"filter knob hit target");a.surface.scroll=Math.max(0,knob.r.centerY()-a.surface.viewport*.5f);a.surface.invalidate();});
        Thread.sleep(300);final float[] points=new float[3];runOnMainSync(()->{LooperView.Hit knob=null;for(LooperView.Hit h:a.surface.hits)if(h.knob==2){knob=h;break;}int[] location=new int[2];a.surface.getLocationOnScreen(location);points[0]=location[0]+a.surface.getPaddingLeft()+knob.r.centerX()*a.surface.density;points[1]=location[1]+a.surface.getPaddingTop()+(knob.r.centerY()-a.surface.scroll)*a.surface.density;points[2]=a.surface.density;});long now=SystemClock.uptimeMillis();getUiAutomation().injectInputEvent(MotionEvent.obtain(now,now,MotionEvent.ACTION_DOWN,points[0],points[1],0),true);getUiAutomation().injectInputEvent(MotionEvent.obtain(now,now+40,MotionEvent.ACTION_MOVE,points[0],points[1]+80*points[2],0),true);Thread.sleep(50);check(a.engine.banks[0].layers.get(0).cutoff<1500,"filter changes before touch release");getUiAutomation().injectInputEvent(MotionEvent.obtain(now,now+80,MotionEvent.ACTION_UP,points[0],points[1]+80*points[2],0),true);runOnMainSync(()->a.engine.banks[0].layers.get(0).cutoff=20000);Thread.sleep(200);runOnMainSync(()->a.monitorToggle());waitForIdleSync();java.util.List<android.view.accessibility.AccessibilityNodeInfo> enable=getUiAutomation().getRootInActiveWindow().findAccessibilityNodeInfosByText("ENABLE");check(!AudioService.monitor&&!enable.isEmpty(),"monitor feedback warning");enable.get(0).performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK);Thread.sleep(150);check(AudioService.monitor,"monitor enabled");runOnMainSync(()->a.monitorToggle());check(!AudioService.monitor,"monitor disabled");Bitmap image=getUiAutomation().takeScreenshot();File screenshot=new File(getTargetContext().getExternalFilesDir(null),"smoke.png");try(FileOutputStream out=new FileOutputStream(screenshot)){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();
        runOnMainSync(()->a.transport(1,1));Thread.sleep(300);check(a.engine.banks[1].recording,"overdub records");runOnMainSync(()->a.transport(1,1));check(!a.engine.banks[1].recording&&a.engine.banks[1].layers.size()==2,"overdub finishes");runOnMainSync(()->a.transport(1,3));check(a.engine.banks[1].layers.size()==1,"undo");runOnMainSync(()->AudioService.current.onTaskRemoved(new Intent()));waitFor(()->AudioService.current==null,"task removal stops service");long stoppedClock=a.engine.clock;Thread.sleep(150);check(a.engine.clock==stoppedClock&&!AudioService.monitor,"task removal stops audio and monitor");result.putString("stream","PASS: Android activity launch; foreground microphone/output; moving sample clock; nonzero loop output; live filter touch drag; monitor warning/enable/disable; overdub/finish/undo; task-removal service/audio stop. Screenshot: "+screenshot);finish(Activity.RESULT_OK,result);}catch(Throwable e){result.putString("stream","FAIL: "+android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,result);}}
}
